        public DataSet IsAnyTestPublishedForStudent(int aiSchoolID, int aiAcademicYrID, int aiStudentId, int aiStanderddivisionId)
        {
            string sFilter = string.Empty;
            if (aiStudentId != 0)
                sFilter = " AND StudentId= " + aiStudentId;
            if (aiStanderddivisionId != 0)
                sFilter = " AND Standard_division_Id= " + aiStanderddivisionId;
            String strSelect = " SELECT " +
                                  " TOP 1 StudentWiseTestPublishStatusId As TestCount " +
                               " FROM StudentWiseTestPublishStatus " +
                               " WHERE  " +
                                    " School_Id= " + aiSchoolID +
                                    " AND Is_Published= N'" + Constants.C_YES + "'" +
                                    " AND Is_Deleted= N'" + Constants.C_NO + "'" +
                                    sFilter +
                                    " AND Academic_Year_ID= " + aiAcademicYrID;

            using (SQLServerDbUtility oSQLServerDbUtility = new SQLServerDbUtility())
                return oSQLServerDbUtility.ExecuteSqlStatementAndGetDataSet(strSelect);
        }

