        public Boolean CheckGradeConfigurations()
        {
            string sSelectstr = "SELECT    " +
                                 "COUNT(Marks_Grades_Configuration_Details.Marks_Grades_Configuration_Detail_ID)" +
                                 " FROM         Marks_Grades_Configuration INNER JOIN " +
                                 " Marks_Grades_Configuration_Details ON " +
                                 " Marks_Grades_Configuration.Marks_Grades_Configuration_Id = " +
                                 " Marks_Grades_Configuration_Details.Marks_Grades_Configuration_Id INNER JOIN " +
                                 " SchoolWise_Standard_Division_Master ON Marks_Grades_Configuration.School_Id = SchoolWise_Standard_Division_Master.School_Id AND " +
                                 " Marks_Grades_Configuration.Academic_Year_Id = SchoolWise_Standard_Division_Master.academic_year_id AND " +
                                 " Marks_Grades_Configuration.Standard_Id = SchoolWise_Standard_Division_Master.Standard_Id INNER JOIN " +
                                 " Standard_Master ON Marks_Grades_Configuration.Standard_Id = Standard_Master.Standard_Id INNER JOIN " +
                                 " Division_Master ON SchoolWise_Standard_Division_Master.Division_Id = Division_Master.Division_Id " +
                                 " WHERE     (Marks_Grades_Configuration.Is_Deleted = 'N') " +
                                 " AND (Marks_Grades_Configuration_Details.Is_Deleted = 'N') AND " +
                                 " (Marks_Grades_Configuration.School_Id = " + moSchoolWiseStanderedDivisionTestMasterStruct.miSchoolid + ") " +
                                 " AND (Marks_Grades_Configuration.Academic_Year_Id = " + moSchoolWiseStanderedDivisionTestMasterStruct.miAcadmicyearid + ") AND " +
                                 " (SchoolWise_Standard_Division_Master.SchoolWise_Standard_Division_Id = " + moSchoolWiseStanderedDivisionTestMasterStruct.miStanderddivisionId + ")";

            // Perform the stetement on server.
            int iCount;
            using (SQLServerDbUtility oSQLServerDbUtility = new SQLServerDbUtility())
                iCount = oSQLServerDbUtility.PerformIntQueryOnSqlServer(sSelectstr);

            // If the count is zero there is no duplication of Buyer login. 
            if (iCount == 0)
                return false;
            else
                return true;
        }


        public bool CheckPassFailConfigurations()
        {
            string sSelectstr = "SELECT " +
                        " Pass_Fail_Criteria.IsFailCriteriaNotApplicable " +
                        " FROM  Pass_Fail_Criteria INNER JOIN " +
                        " SchoolWise_Standard_Division_Master ON Pass_Fail_Criteria.Standard_Id " +
                        " = SchoolWise_Standard_Division_Master.Standard_Id AND " +
                        " Pass_Fail_Criteria.School_Id = SchoolWise_Standard_Division_Master.School_Id AND " +
                        " Pass_Fail_Criteria.Academic_Year_Id = SchoolWise_Standard_Division_Master.academic_year_id " +
                        " WHERE (SchoolWise_Standard_Division_Master.SchoolWise_Standard_Division_Id = " + moSchoolWiseStanderedDivisionTestMasterStruct.miStanderddivisionId + ")" +
                        " AND (SchoolWise_Standard_Division_Master.School_Id = " + moSchoolWiseStanderedDivisionTestMasterStruct.miSchoolid + ") AND " +
                        " (SchoolWise_Standard_Division_Master.academic_year_id = " + moSchoolWiseStanderedDivisionTestMasterStruct.miAcadmicyearid + ") ";

            // Perform the stetement on server.
            string sIsFailCriteriaNotApplicable = string.Empty;
            using (SQLServerDbUtility oSQLServerDbUtility = new SQLServerDbUtility())
                sIsFailCriteriaNotApplicable = oSQLServerDbUtility.PerformStringQueryOnSqlServer(sSelectstr);

            // If the count is zero there is no duplication of Buyer login. 
            //if (iCount == 0)
            if (string.IsNullOrEmpty(sIsFailCriteriaNotApplicable))
                return false;
            else
                return true;
        }

