        public bool IsDependent(int aiUserId, int aiSchoolId, int aiAcademicYearId)
        {
            string sSelectStatement = " SELECT COUNT(Teacher_Id) FROM vw_ClassTeacher " +
                                     " WHERE  vw_ClassTeacher.User_Id = " + aiUserId +
                                     " AND School_Id = " + aiSchoolId +
                                     " AND Academic_Year_Id = " + aiAcademicYearId +
                                     " AND vw_ClassTeacher.Standard_Id NOT IN ( select Value_Member from vw_Is_Primary_Standard " +
                                     " where School_Id=" + aiSchoolId +
                                     " and Academic_Year_Id=" + aiAcademicYearId + ")";
            int iCount;
            using (SQLServerDbUtility oSQLServerDbUtility = new SQLServerDbUtility())
                iCount = oSQLServerDbUtility.PerformIntQueryOnSqlServer(sSelectStatement);

            // If the count is zero there is no duplication of Buyer login. 
            if (iCount == 0)
                return false;
            else
                return true;
        }

        /// <summary>
        /// This method is used to check whether term exam is published.
        /// </summary>
        /// <param name="aiSchoolId"></param>
        /// <param name="aiAcademicYearId"></param>
        /// <param name="aiStandardDivisionId"></param>
        /// <returns></returns>
        public bool IsTermExamPublished(int aiSchoolId, int aiAcademicYearId, int aiStandardDivisionId, out string asStandardName)
        {
            using (SQLServerDbUtility oSQLServerDbUtility = new SQLServerDbUtility())
            {
                oSQLServerDbUtility.AddParameter("SchoolId", aiSchoolId, SqlDbType.Int);
                oSQLServerDbUtility.AddParameter("AcademicYearId", aiAcademicYearId, SqlDbType.Int);
                oSQLServerDbUtility.AddParameter("StandardDivisionId", aiStandardDivisionId, SqlDbType.Int);
                SqlParameter oSqlParameter = oSQLServerDbUtility.AddParameter("IsPublished", 0, SqlDbType.Bit, ParameterDirection.Output);
                SqlParameter aoSqlParameter = oSQLServerDbUtility.AddParameter("StandardName", 0, SqlDbType.NVarChar, ParameterDirection.Output,100);
                oSQLServerDbUtility.ExecuteStoredProcedureOnServer("usp_IsTermExamPublished");
                asStandardName = aoSqlParameter.Value.ToString();
                return oSqlParameter.Value.ToBool();
            }
        }

